  public void renameIfExistingTask(String taskName)
  {
  	TaskDefinition existing=context.getObjectByName(TaskDefinition.class,taskName);
    if(existing !=null)
    {
    	String newName=taskName+"-OLD";
      existing.setName(newName);
      context.saveObject(existing);
      context.commitTransaction();
    }
  }

  public void createGroupAggregationTask(String appName)
  {
  	String taskName="Sky-groupAggregation-"+appName;
    renameIfExistingTask(taskName);

    TaskDefinition task=new TaskDefinition();

    task.setName(taskName);
    task.setType(Type.AccountGroupAggregation);
    task.setSubType("task_item_type_acct_grp_aggregation");
    task.setResultAction(TaskDefinition.ResultAction.Delete);
    task.setFormPath("/monitor/tasks/accountGroupAggregationTask.xhtml");
    task.setOwner(context.getObjectByName(Identity.class,"spadmin"));
    task.setParent(context.getObjectByName(TaskDefinition.class,"Account Group Aggregation"));

    Attributes attrs=new Attributes();
    attrs.put("applications",appName);
    attrs.put("aggregationType","group");
		attrs.put("checkDeleted","false");
    attrs.put("deltaAggregation","false");
		attrs.put("descriptionLocale","en_US");
    attrs.put("enablePartitioning","false");
		attrs.put("groupSchema","");
    attrs.put("haltOnMaxError","false");
		attrs.put("promoteClassifications","false");
		attrs.put("accountGroupRefreshRule","Sky-groupAgg-Rule");
    attrs.put("taskCompletionEmailNotify","Disable");
    attrs.put("taskCompletionEmailRecipients","");
    attrs.put("taskCompletionEmailTemplate","");


    task.setArguments(attrs);
    context.saveObject(task);
    context.commitTransaction();             
  }

